import re


def _parse_version(version_str: str) -> tuple:
    """
    Sürüm string'ini parse eder ve tuple olarak döndürür.
    Tuple: (major, minor, patch, prereleases=[], is_dev=False)
    """
    # v ile başlayıp başlamadığını kontrol et
    version_str = version_str.lstrip('v')

    # Ana sürüm numarasını ayır
    core_match = re.match(r'^(\d+)\.(\d+)\.(\d+)(?:-(.+))?(?:\+(.+))$', version_str)
    if not core_match:
        raise ValueError(f"Geçersiz sürüm formatı: {version_str}")

    major, minor, patch, prerelease, build = core_match.groups()

    # Numaraların geçerliliğini kontrol et (0 hariç başta)
    for name, val in [("major", major), ("minor", minor), ("patch", patch)]:
        if not val.isdigit():
            raise ValueError(f"{name} numarası geçersiz: {version_str}")
        num = int(val)
        if num < 0:
            raise ValueError(f"{name} numarası negatif: {version_str}")

    # Prerelease kimliklerini parse et (SemVer kurallarına göre)
    prereleases = []
    if prerelease:
        # Prerelease kimlikleri: alfanümerik, nokta ile ayrılmış
        # Her kimlik: sayısal veya alfanümerik
        prerelease_ids = prerelease.split('.')
        for pid in prerelease_ids:
            if pid == '':
                raise ValueError(f"Prerelease kimliği boş: {version_str}")
            # Prerelease kimlikleri: sayısal veya alfanümerik karakterlerden oluşmalı
            # SemVer 2.0: alfanümerik, ancak sayısal kısımlar sayısal olarak karşılaştırılır
            if pid and not all(c.isalnum() or c == '-' or c == '_' or c == '+' or c == '.' for c in pid):
                raise ValueError(f"Geçersiz prerelease kimliği: {version_str}")
            prereleases.append(pid)

    return (int(major), int(minor), int(patch), prereleases, False)


def _compare_prereleases(prereleases1: list, prereleases2: list) -> int:
    """
    Prerelease kimliklerini SemVer kuralına göre karşılaştırır.
    Prereleses olan sürüm, olmayan sürümden öncelikle düşüktür.
    """
    # Prereleases olmayan (boş liste) sona koyulur
    if not prereleases1 and prereleases2:
        return -1
    if prereleases1 and not prereleases2:
        return 1
    if not prereleases1 and not prereleases2:
        return 0

    # Her iki sürümde de prerelease var
    for i in range(max(len(prereleases1), len(prereleases2))):
        id1 = prereleases1[i] if i < len(prereleases1) else ''
        id2 = prereleases2[i] if i < len(prereleases2) else ''

        # Her iki kimlik de sayısal ise sayısal karşılaştırma
        if id1.isdigit() and id2.isdigit():
            if id1 != id2:
                return -1 if int(id1) < int(id2) else 1
        # Her iki kimlik de alfanümerik ise string karşılaştırma
        elif id1.isalnum() and id2.isalnum():
            if id1 != id2:
                return -1 if id1 < id2 else 1
        # Birisi sayısal, birisi alfanümerik
        # Sayısal kimlik alfanümerikten önce gelir
        if id1.isdigit() and id2.isalnum():
            return -1
        if id1.isalnum() and id2.isdigit():
            return 1

    # Uzunluk farkı (daha kısa olan önce)
    if len(prereleases1) != len(prereleases2):
        return -1 if len(prereleases1) < len(prereleases2) else 1

    return 0


def _compare_versions(v1: tuple, v2: tuple) -> int:
    """
    İki parse edilmiş sürüm tuple'ını karşılaştırır.
    """
    # MAJOR karşılaştırması
    if v1[0] != v2[0]:
        return -1 if v1[0] < v2[0] else 1

    # MINOR karşılaştırması
    if v1[1] != v2[1]:
        return -1 if v1[1] < v2[1] else 1

    # PATCH karşılaştırması
    if v1[2] != v2[2]:
        return -1 if v1[2] < v2[2] else 1

    # Prerelease karşılaştırması
    return _compare_prereleases(v1[3], v2[3])


def compare(a: str, b: str) -> int:
    """
    İki sürüm string'ini karşılaştırır.
    a < b ise -1, eşitse 0, a > b ise 1 döndürür.
    """
    v1 = _parse_version(a)
    v2 = _parse_version(b)
    return _compare_versions(v1, v2)


def sort_versions(versions: list) -> list:
    """
    Sürümleri önceliğe göre artan sıralar.
    Eşit öncelikli sürümler girdideki sıralarını korur (stabil sort).
    """
    return sorted(versions, key=lambda v: _parse_version(v))

